<template><div class="fit column"><div class="col-auto"><div class="row items-center q-pa-lg"><div class="col-grow"><app-btn-back @click="emits('back')" /></div></div></div><div class="col full-height q-px-lg q-pb-lg"><q-card flat class="full-height"><q-form class="full-height" @submit="submit"><q-card-section class="q-pa-lg scroll"><div class="row q-col-gutter-md"><app-input v-model="store.form.kode" class="col-12 col-sm-6" label="Kode Shift" :valid="{ required: true }" /><app-input v-model="store.form.nama" class="col-12 col-sm-6" label="Nama Shift" :valid="{ required: true }" /><q-input v-model="store.form.jam_masuk" class="col-12 col-sm-6" outlined dense label="Jam Masuk (24 jam)" mask="##:##" fill-mask="0" hint="Format HH:MM, contoh 08:00" /><q-input v-model="store.form.jam_keluar" class="col-12 col-sm-6" outlined dense label="Jam Pulang (24 jam)" mask="##:##" fill-mask="0" hint="Format HH:MM, contoh 17:00" /><app-input v-model.number="store.form.toleransi" class="col-12 col-sm-6" label="Toleransi (menit)" type="number" /><q-toggle v-model="aktif" class="col-12 col-sm-6" label="Shift aktif" /><div class="col-12"><q-separator class="q-my-md" /><app-btn :loading="store.loading" type="submit" label="Simpan" color="grey-10" class="text-yellow-9" /></div></div></q-card-section></q-form></q-card></div></div></template>
<script setup>
import { computed, onMounted } from 'vue'
import { useAdminFormMasterShiftKerjaStore } from 'src/stores/admin/master/shiftkerja/form'
const props = defineProps({ data: { type: Object, default: null } }); const emits = defineEmits(['back']); const store = useAdminFormMasterShiftKerjaStore(); const aktif = computed({ get: () => Boolean(Number(store.form.aktif)), set: (value) => { store.form.aktif = value ? 1 : 0 } }); onMounted(() => store.initReset(props.data)); function submit() { store.save(props.data) }
</script>
